(* Writes the Verilog Tiny Tapeout consumes: the top module and every submodule, one file. *)

open! Core
open! Hardcaml

let header =
  "// GENERATED by rtl/bin/generate.ml from the Hardcaml sources in rtl/src. Do not edit:\n\
   // change the OCaml and run `make rtl`.\n"
;;

let () =
  let out =
    match Sys.get_argv () with
    | [| _; out |] -> out
    | _ -> failwith "usage: generate.exe OUTPUT.v"
  in
  let scope = Scope.create ~flatten_design:false () in
  let module C = Circuit.With_interface (Golem.Top.I) (Golem.Top.O) in
  let circuit = C.create_exn ~name:Golem.Top.module_name (Golem.Top.create scope) in
  let buffer = Buffer.create 65536 in
  Rtl.output
    ~database:(Scope.circuit_database scope)
    ~output_mode:(To_buffer buffer)
    Verilog
    circuit;
  (* The Tiny Tapeout top has fixed ports, some unused by a given wiring (e.g. [ena]).
     Silence unused-signal lint for that module only; design blocks stay fully linted. *)
  let verilog = Buffer.contents buffer in
  let top = "module " ^ Golem.Top.module_name in
  let verilog =
    match String.substr_index verilog ~pattern:top with
    | None -> failwith "top module not found in generated Verilog"
    | Some at ->
      String.prefix verilog at
      ^ "/* verilator lint_off UNUSEDSIGNAL */\n"
      ^ String.drop_prefix verilog at
      ^ "/* verilator lint_on UNUSEDSIGNAL */\n"
  in
  Out_channel.write_all out ~data:(header ^ verilog)
;;
